mkdir -p /app/output/assets && cat > /app/output/assets/styles.css <<'CSS'
:root {
  --navy: #0a1628;
  --navy-2: #0f223b;
  --white: #ffffff;
  --gray-50: #f6f8fb;
  --gray-100: #edf1f6;
  --gray-300: #c9d2df;
  --gray-500: #6f7f93;
  --gray-700: #32455f;
  --teal: #0f8a8a;
  --gold: #b08a3f;
  --max: 1200px;
  --shadow: 0 18px 48px rgba(10, 22, 40, 0.16);
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  color: var(--navy);
  background: var(--white);
  line-height: 1.6;
}
h1,h2,h3,h4 {
  font-family: 'Playfair Display', Georgia, serif;
  margin: 0 0 .6rem;
  line-height: 1.2;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(var(--max), 92vw); margin: 0 auto; }
.btn { display:inline-block; padding:.8rem 1.2rem; border-radius:2px; font-weight:600; }
.btn-primary { background: var(--gold); color: #111; }
.btn-outline { border:1px solid var(--white); color:var(--white); }
.top-banner {
  background: var(--teal);
  color: var(--white);
  font-size: .92rem;
  padding: .55rem 0;
}
.header {
  position: sticky; top:0; z-index: 60;
  background: rgba(10,22,40,.97); color: var(--white);
  border-bottom: 1px solid rgba(255,255,255,.09);
}
.header-row { display:flex; align-items:center; justify-content:space-between; min-height:78px; }
.brand { font-size: 1.35rem; letter-spacing:.04em; font-weight:700; }
.nav { display:flex; gap:1.4rem; align-items:center; }
.nav > li { list-style:none; position:relative; }
.nav-link { padding:.4rem .2rem; font-size:.95rem; color: rgba(255,255,255,.95); }
.nav-link:hover { color: var(--gold); }
.mega {
  position:absolute; left:0; top:calc(100% + 16px);
  width: min(920px, 90vw); background: var(--white); color:var(--navy);
  box-shadow: var(--shadow); border-radius:4px; padding:1.2rem 1.2rem 1rem;
  display:none;
}
.nav li.open .mega { display:block; }
.mega-grid { display:grid; grid-template-columns: 2fr 1fr; gap:1rem 2rem; }
.mega h4 { font-family:'Plus Jakarta Sans',sans-serif; font-size:.88rem; letter-spacing:.08em; text-transform:uppercase; color:var(--gray-500); }
.mega ul { margin: .2rem 0 0; padding:0; }
.mega li { list-style:none; padding:.36rem 0; border-bottom:1px solid var(--gray-100); font-size:.95rem; }
.mobile-toggle { display:none; background:none; border:none; color:white; font-size:1.7rem; }
.mobile-menu { display:none; background:var(--navy); color:var(--white); padding:0 .9rem 1rem; }
.mobile-menu.open { display:block; }
.mob-acc summary { cursor:pointer; padding:.8rem 0; font-weight:600; }
.mob-acc a { display:block; padding:.45rem 0 .45rem 1rem; color:rgba(255,255,255,.9); }
.hero {
  min-height: 64vh; color: var(--white); position:relative;
  background-size:cover; background-position:center;
}
.hero::before { content:''; position:absolute; inset:0; background:linear-gradient(85deg, rgba(10,22,40,.88), rgba(10,22,40,.45)); }
.hero-content { position:relative; padding: 7rem 0 5rem; max-width: 760px; }
.kicker { text-transform:uppercase; letter-spacing:.12em; font-size:.8rem; color:#d5dfec; }
.section { padding: 4.5rem 0; }
.alt { background: var(--gray-50); }
.grid-3 { display:grid; grid-template-columns: repeat(3,1fr); gap:1.2rem; }
.grid-2 { display:grid; grid-template-columns: repeat(2,1fr); gap:1.2rem; }
.card { background:#fff; border:1px solid var(--gray-100); padding:1.2rem; }
.card h3 { font-size:1.28rem; }
.meta { color:var(--gray-500); font-size:.88rem; }
.service-link { color:var(--teal); font-weight:700; font-size:.92rem; }
.tabs-wrap { display:grid; grid-template-columns: 260px 1fr; gap:1.4rem; }
.tab-buttons button {
  width:100%; text-align:left; padding:1rem; border:1px solid var(--gray-100);
  background:#fff; margin-bottom:.6rem; cursor:pointer; font-weight:600;
}
.tab-buttons button.active { border-left:4px solid var(--gold); background:#fbf8f2; }
.tab-panel { display:none; background:#fff; border:1px solid var(--gray-100); padding:1.2rem; min-height:220px; }
.tab-panel.active { display:block; }
.newsletter { background:var(--navy); color:#fff; padding:2rem; display:flex; justify-content:space-between; gap:1rem; align-items:center; }
.newsletter input { padding:.8rem; min-width:260px; border:none; }
.footer { background:var(--navy); color:#ced7e4; padding:2.6rem 0; font-size:.9rem; }
.footer-grid { display:grid; grid-template-columns: 2fr 1fr 1fr; gap:1rem; }
.carousel { position:relative; overflow:hidden; }
.carousel-track { display:flex; transition: transform .35s ease; }
.slide { min-width:100%; padding:1.2rem; background:#fff; border:1px solid var(--gray-100); }
.carousel-controls { display:flex; gap:.6rem; margin-top:.8rem; }
.ctrl { border:1px solid var(--gray-300); background:#fff; padding:.45rem .8rem; cursor:pointer; }
@media (max-width: 980px) {
  .nav { display:none; }
  .mobile-toggle { display:block; }
  .grid-3 { grid-template-columns:1fr 1fr; }
  .tabs-wrap { grid-template-columns:1fr; }
}
@media (max-width: 700px) {
  .grid-3,.grid-2,.footer-grid { grid-template-columns:1fr; }
  .hero-content { padding:5.4rem 0 3.8rem; }
  .newsletter { flex-direction:column; align-items:flex-start; }
}
